class ActivitySummaryTest {

    private ActivityEvent e(ActivityEvent.Type t, long q) {
        return new ActivityEvent(1, "2026-09-23T12:34:56Z", t, List.of("minecraft:diamond"), q, ActivityEvent.Source.MANUAL);
    }

    @Test
    void countsAllTypes() {
        var s = ActivitySummary.from(List.of(e(ActivityEvent.Type.ITEM_GAINED, 2), e(ActivityEvent.Type.ITEM_LOST, 3)));
        assertEquals(2, s.eventCount());
        assertEquals(5, s.totalQuantity());
        for (var t : ActivityEvent.Type.values())
            assertNotNull(s.counts().get(t));
        assertEquals(1, s.counts().get(ActivityEvent.Type.ITEM_GAINED));
    }

    @Test
    void emptyAndImmutable() {
        var s = ActivitySummary.from(List.of());
        assertEquals(0, s.totalQuantity());
        assertThrows(UnsupportedOperationException.class, () -> s.counts().clear());
    }

    @Test
    void rejectsNull() {
        assertThrows(RuntimeException.class, () -> ActivitySummary.from(null));
        assertThrows(RuntimeException.class, () -> ActivitySummary.from(java.util.Arrays.asList((ActivityEvent) null)));
    }

    @Test
    void testQuantitiesByType() {
        var s = ActivitySummary.from(List.of(e(ActivityEvent.Type.ITEM_GAINED, 2), e(ActivityEvent.Type.ITEM_LOST, 3)));
        var quantitiesByType = s.quantitiesByType();
        assertEquals(2, quantitiesByType.get(ActivityEvent.Type.ITEM_GAINED));
        assertEquals(3, quantitiesByType.get(ActivityEvent.Type.ITEM_LOST));
        assertEquals(2, quantitiesByType.size());
    }
}

class ActivityHistoryTest {

    private ActivityEvent e(String id) {
        return new ActivityEvent(1, "2026-09-23T12:34:56Z", ActivityEvent.Type.ITEM_GAINED, List.of(id), 1L, ActivityEvent.Source.MANUAL);
    }

    @Test
    void boundedAndOrdered() {
        var h = new ActivityHistory(2);
        h.append(e("minecraft:a"));
        h.append(e("minecraft:b"));
        h.append(e("minecraft:c"));
        assertEquals(List.of(e("minecraft:b"), e("minecraft:c")), h.recent());
        assertEquals(2, h.size());
    }

    @Test
    void immutableAndClear() {
        var h = new ActivityHistory(1);
        h.append(e("minecraft:a"));
        assertThrows(UnsupportedOperationException.class, () -> h.recent().clear());
        h.clear();
        assertEquals(0, h.size());
    }

    @Test
    void rejectsInvalid() {
        assertThrows(RuntimeException.class, () -> new ActivityHistory(0));
        assertThrows(RuntimeException.class, () -> new ActivityHistory(257));
        assertThrows(RuntimeException.class, () -> new ActivityHistory(1).append(null));
    }

    @Test
    void testSummary() {
        var h = new ActivityHistory(2);
        h.append(e("minecraft:a"));
        h.append(e("minecraft:b"));
        var summary = h.summary();
        assertEquals(2, summary.eventCount());
        assertEquals(2, summary.totalQuantity());
        assertEquals(1, summary.counts().get(ActivityEvent.Type.ITEM_GAINED));
        assertEquals(1, summary.counts().get(ActivityEvent.Type.ITEM_LOST));
    }
}

